export const APP_LOCALE_CODES = [
  'ar',
  'zh',
  'en',
  'fr',
  'de',
  'hi',
  'it',
  'ja',
  'fa',
  'ru',
  'es',
  'tr',
] as const;

export function isAppLocale(value: string | null | undefined): value is SupportedLocale {
  return Boolean(value && (APP_LOCALE_CODES as readonly string[]).includes(value));
}

