function buildCatalogs(): Record<AppLang, Record<string, string>> {
  const catalogs = Object.fromEntries(LANGS.map((lang) => [lang, {} as Record<string, string>])) as Record<
    AppLang,
    Record<string, string>
  >;

  for (const [key, row] of Object.entries({ ...RAW, ...MARKETING_RAW })) {
    LANGS.forEach((lang, index) => {
      catalogs[lang][key] = row[index];
    });
  }

  return catalogs;
}

export const CATALOGS: Partial<Record<SupportedLocale, Record<string, string>>> = buildCatalogs();

export function interpolate(template: string, vars?: Record<string, string | number>): string {
  if (!vars) {
    return template;
  }
  return template.replace(/\{(\w+)\}/g, (_, name: string) =>
    vars[name] === undefined || vars[name] === null ? `{${name}}` : String(vars[name]),
  );
}

export function translate(
  locale: SupportedLocale,
  key: string,
  vars?: Record<string, string | number>,
): string {
  const resolved = isAppLocale(locale) ? locale : 'en';
  const text = CATALOGS[resolved]?.[key] ?? CATALOGS.en?.[key] ?? key;
  return interpolate(text, vars);
}
